import { execSync } from 'child_process';
import { writeFileSync, existsSync } from 'fs';
import assert from 'assert';

// Compile TypeScript
execSync('tsc --target ES2020 --module commonjs --strict event_bus.ts', { stdio: 'pipe' });

// Load compiled JS
const { EventBus } = await import('./event_bus.js');

// Basic on/emit
const bus = new EventBus();
const calls = [];
const h1 = (x) => calls.push(x);
bus.on('greet', h1);
bus.emit('greet', 'hello');
assert.deepStrictEqual(calls, ['hello'], 'h1 called with hello');

// Multiple handlers
const h2 = (x) => calls.push('h2:' + x);
bus.on('greet', h2);
bus.emit('greet', 'world');
assert.ok(calls.includes('world'), 'h1 called on second emit');
assert.ok(calls.includes('h2:world'), 'h2 called on second emit');

// off removes only the specified handler
bus.off('greet', h1);
calls.length = 0;
bus.emit('greet', 'again');
assert.ok(!calls.includes('again'), 'h1 should not be called after off');
assert.ok(calls.includes('h2:again'), 'h2 still called after h1 removed');

// off no-op for unknown handler
bus.off('greet', () => {});  // should not throw

// emit unknown event is no-op
bus.emit('unknown_event');

// Multi-arg emit
const bus2 = new EventBus();
let received = null;
bus2.on('data', (a, b) => { received = [a, b]; });
bus2.emit('data', 42, 'hello');
assert.deepStrictEqual(received, [42, 'hello'], 'multi-arg emit');

