jobs.description:
Implement `deepClone(value)` in `deepClone.js`. The function must handle:

- Primitives (number, string, boolean, null, undefined): return as-is
- Plain objects `{}`: deep copy all own enumerable properties
- Arrays `[]`: deep copy all elements
- `Date` instances: return `new Date(original.getTime())`
- `Map` instances: return a new `Map` with deep-cloned keys and values
- Nested combinations of the above

## Constraints
- No external dependencies (Node.js stdlib only)
- Must use `export default deepClone` (ES module)
- Do NOT use `JSON.parse(JSON.stringify(...))` (it breaks Dates and Maps)
- Do NOT use `structuredClone` (implement manually)

## Test contract
```js
const obj = { a: 1, b: { c: [2, 3] }, d: new Date(0), e: new Map([["x", {y: 9}]]) };
const clone = deepClone(obj);
clone.b.c.push(99);
clone.e.get("x").y = 999;
// original must be unaffected
assert(obj.b.c.length === 2);
assert(obj.e.get("x").y === 9);
assert(clone.d.getTime() === 0);
```

success_condition.test_code:
import deepClone from './deepClone.js';
import assert from 'assert';

// primitives
assert(deepClone(42) === 42);
assert(deepClone("hi") === "hi");
assert(deepClone(null) === null);
assert(deepClone(undefined) === undefined);

// array independence
const arr = [1, [2, 3]];
const arrClone = deepClone(arr);
arrClone[1].push(99);
assert(arr[1].length === 2, "original array must be unaffected");

// object independence
const obj = { a: 1, b: { c: 2 } };
const objClone = deepClone(obj);
objClone.b.c = 999;
assert(obj.b.c === 2, "original object must be unaffected");

// Date
const d = new Date(1000);
const dClone = deepClone(d);
assert(dClone instanceof Date, "Date clone must be a Date");
assert(dClone.getTime() === 1000, "Date value preserved");
dClone.setTime(9999);
assert(d.getTime() === 1000, "original Date must be unaffected");

// Map
const m = new Map([["key", { val: 1 }]]);
const mClone = deepClone(m);
mClone.get("key").val = 999;
assert(m.get("key").val === 1, "original Map value must be unaffected");

