const light = new StateMachine("red", [
  { from: "red",    event: "next", to: "green"  },
  { from: "green",  event: "next", to: "yellow" },
  { from: "yellow", event: "next", to: "red"    },
]);

console.assert(light.getState() === "red", "initial state");
console.assert(light.send("next") === true, "send next from red");
console.assert(light.getState() === "green", "state after next");
console.assert(light.send("next") === true, "send next from green");
console.assert(light.getState() === "yellow", "state after next from green");
console.assert(light.send("invalid") === false, "invalid event returns false");
console.assert(light.getState() === "yellow", "state unchanged on invalid");

