  const r1 = await retry(() => { callCount++; return Promise.resolve("ok"); }, { maxAttempts: 3, baseDelayMs: 1 });
  assert(r1 === "ok", "Should return resolved value");
  assert(callCount === 1, "Should call once on immediate success");

  // Succeeds on 3rd attempt
