    return Promise.resolve("done");
  }, { maxAttempts: 3, baseDelayMs: 5, factor: 2 });
  assert(r2 === "done", "Should return success on 3rd attempt");
  assert(calls === 3, "Should have called 3 times");

  // Throws after maxAttempts
