  }
  assert(failCalls === 3, "Should have attempted 3 times");

  // Default options (maxAttempts=3)
  let defCalls = 0;
  try {
    await retry(() => { defCalls++; return Promise.reject(new Error("fail")); }, { baseDelayMs: 1 });
  } catch {}
  assert(defCalls === 3, "Default maxAttempts should be 3");

  console.log("ALL TESTS PASSED");
})().catch(err => { console.error(err); process.exit(1); });

