package main

import (
  "fmt"
  "reflect"
  "testing"
)

func TestBST(t *testing.T) {
  b := &BST{}

  // Empty tree
  if b.Search(5) { t.Fatal("Search on empty should return false") }
  if b.Height() != 0 { t.Fatalf("Empty tree height should be 0, got %d", b.Height()) }
  if got := b.InOrder(); len(got) != 0 { t.Fatalf("InOrder on empty should be [], got %v", got) }

  // Insert and search
  for _, v := range []int{5, 3, 7, 1, 4, 6, 8} {
    b.Insert(v)
  }
  if !b.Search(5) { t.Fatal("Search(5) should be true") }
  if !b.Search(1) { t.Fatal("Search(1) should be true") }
  if !b.Search(8) { t.Fatal("Search(8) should be true") }
  if b.Search(99) { t.Fatal("Search(99) should be false") }
  if b.Search(0) { t.Fatal("Search(0) should be false") }

  // In-order
  got := b.InOrder()
  want := []int{1, 3, 4, 5, 6, 7, 8}
  if !reflect.DeepEqual(got, want) { t.Fatalf("InOrder want %v got %v", want, got) }

  // Height: root=5, left=3, right=7, children at depth 2 (1,4,6,8) → height=3
  h := b.Height()
  if h != 3 { t.Fatalf("Height should be 3, got %d", h) }

  // Duplicate insert is no-op
  b.Insert(5)
  got2 := b.InOrder()
  if !reflect.DeepEqual(got2, want) { t.Fatalf("Duplicate insert changed InOrder: %v", got2) }

  // Single node height
  b2 := &BST{}
  b2.Insert(42)
  if b2.Height() != 1 { t.Fatalf("Single node height should be 1, got %d", b2.Height()) }

  fmt.Println("ALL TESTS PASSED")
}
GOTEST

