#!/bin/bash
set -e

test -f emitter.test.ts || { echo "FAIL: emitter.test.ts not found"; exit 1; }

# Write emitter.ts implementation
cat > emitter.ts << 'EOF'
export class TypedEmitter<Events extends Record<string, unknown[]>> {
  private listeners: Map<keyof Events, Array<(...args: unknown[]) => void>> = new Map();

  on<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event)!.push(listener as (...args: unknown[]) => void);
    return this;
  }

  off<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    const arr = this.listeners.get(event) || [];
    const idx = arr.indexOf(listener as (...args: unknown[]) => void);
    if (idx !== -1) arr.splice(idx, 1);
    return this;
  }

  emit<K extends keyof Events>(event: K, ...args: Events[K]): boolean {
    const arr = this.listeners.get(event) || [];
    if (arr.length === 0) return false;
    arr.slice().forEach(fn => fn(...args));
    return true;
  }

  once<K extends keyof Events>(event: K, listener: (...args: Events[K]) => void): this {
    const wrapper = (...args: unknown[]) => {
      this.off(event, listener);
      (listener as (...args: unknown[]) => void)(...args);
    };
    return this.on(event, wrapper as (...args: Events[K]) => void);
  }

  listenerCount<K extends keyof Events>(event: K): number {
    return (this.listeners.get(event) || []).length;
  }
}
EOF

