jobs.description:
Implement a `ConcurrencyLimiter` class in `concurrency_limiter.ts` that runs async tasks with a maximum concurrency cap.

## Interface
```typescript
class ConcurrencyLimiter {
  constructor(maxConcurrent: number);

  // Add a task (async function) to the queue.
  // Returns a Promise that resolves to the task's return value.
  add<T>(task: () => Promise<T>): Promise<T>;

  // Wait until all queued/running tasks finish.
  waitAll(): Promise<void>;

  // Current number of running tasks (not queued).
  get running(): number;

  // Current number of queued tasks (waiting to run).
  get pending(): number;
}
```

## Test assertions (must all pass)
```typescript
import { ConcurrencyLimiter } from './concurrency_limiter';

async function delay(ms: number): Promise<number> {
  return new Promise(resolve => setTimeout(() => resolve(ms), ms));
}

async function runTests() {
  // Basic concurrency cap
  const limiter = new ConcurrencyLimiter(2);
  const log: string[] = [];

  const results: Promise<number>[] = [];
  for (let i = 1; i <= 4; i++) {
    results.push(limiter.add(async () => {
      log.push(`start:${i}`);
      await delay(10);
      log.push(`end:${i}`);
      return i * 10;
    }));
  }

  await limiter.waitAll();

  // All 4 tasks completed
  const resolved = await Promise.all(results);
  console.assert(resolved.length === 4, 'Should resolve 4 tasks');
  console.assert(resolved.includes(10), 'Should include 10');
  console.assert(resolved.includes(40), 'Should include 40');

  // Max 2 ran concurrently at any point — log has interleaved starts
  const starts = log.filter(l => l.startsWith('start'));
  console.assert(starts.length === 4, 'All 4 tasks should have started');

  // Return value correctness
  const single = new ConcurrencyLimiter(1);
  const r = await single.add(async () => 'hello');
  console.assert(r === 'hello', 'Should return task result');

  // pending/running counters
  const limiter2 = new ConcurrencyLimiter(1);
  const t1 = limiter2.add(() => delay(50));
  const t2 = limiter2.add(() => delay(50));
  // Give event loop a tick
  await new Promise(r => setTimeout(r, 5));
  console.assert(limiter2.running === 1, `running should be 1, got ${limiter2.running}`);
  console.assert(limiter2.pending === 1, `pending should be 1, got ${limiter2.pending}`);
  await Promise.all([t1, t2]);

  console.log('ALL TESTS PASSED');
}

runTests().catch(e => { console.error(e); process.exit(1); });
```

## Constraints
- No external dependencies
- Compiled with `tsc --strict --target ES2020`
- Export `ConcurrencyLimiter` as a named export
- Under 80 lines

